INSERT INTO "messages" VALUES(1,'architect','На 11 декабря планирую две итерации. Каталог – 8 ч, маршрут – 8 ч, обработка ошибок – 4 ч. Во второй неделе: текстовый обзор – 12 ч, ссылка с предпросмотром – 8 ч. Всего 40 ч, 1600 BYN.');
INSERT INTO "messages" VALUES(1,'alexander','Почему восемь часов на ссылку? Для первого выпуска достаточно, чтобы человек открыл нужный отзыв. Ошибку базы я бы проверил ещё до показа маршрутов.');
INSERT INTO "messages" VALUES(1,'architect','Из восьми часов четыре уходят на карточку предпросмотра и проверку отображения. Оставим обычную ссылку: два часа на открытие по идентификатору и два на проверку чужого клиента и неизвестного адреса.');
INSERT INTO "messages" VALUES(1,'alexander','Подходит. Сначала проверьте загрузку и ошибку, затем покажите маршрут. Предпросмотр отложим. Сколько остаётся?');
INSERT INTO "messages" VALUES(1,'architect','В первой итерации 20 ч, во второй 16 ч. Итого 36 ч и 1440 BYN. Дата та же, запас – четыре часа.');
INSERT INTO "messages" VALUES(1,'alexander','Принимаю этот вариант для следующего обсуждения.');
INSERT INTO "messages" VALUES(2,'alexander','Передумал насчёт текстового отзыва. Для меня важно, чтобы турист мог приложить две фотографии. Получатель ссылки должен увидеть оба снимка.');
INSERT INTO "messages" VALUES(2,'architect','Это ещё 8 ч: выбор файлов – 2, проверка и сохранение – 3, вывод – 1, интеграция и проверка – 2. Одному потребуется 44 ч. При четырёх часах в день выпуск переносится на 14 декабря.');
INSERT INTO "messages" VALUES(2,'alexander','11 декабря уже назначен показ. Дату оставляем. Могу выделить до 1650 BYN, если фотографии войдут в выпуск.');
INSERT INTO "messages" VALUES(2,'architect','Предлагаю junior на 6 ч для выбора, сохранения и вывода снимков. Я заранее задам формат вложения и возьму интеграцию и проверку – 2 ч. Получится 38 ч моей работы и 6 ч junior: 1640 BYN.');
INSERT INTO "messages" VALUES(2,'alexander','А если снимок не читается? Не хочу, чтобы получатель видел наполовину опубликованную запись.');
INSERT INTO "messages" VALUES(2,'architect','При ошибке вложения оставляем запись черновиком. На показе открываем ссылку во втором клиенте и сверяем текст и оба снимка. Дата 11 декабря, итог 1640 BYN.');
INSERT INTO "messages" VALUES(2,'alexander','Такой план принимаю в рамках сценария: обычная ссылка, две фотографии, без предпросмотра.');
INSERT INTO "profiles" VALUES('alexander');
INSERT INTO "profiles" VALUES('architect');
